using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceSecondActionLogic_RandomTarget", menuName = "Data/Battle/Logics/Dice Action/Dice Second Action Logic/DiceSecondActionLogic_RandomTarget")]
public class DiceSecondActionLogic_RandomTarget : DiceSecondActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	public override void OnDrop(ActionFace actionFace, GameObject target, GameObject source)
	{
		GameObject gameObject = null;
		gameObject = currentActiveUnits.GetCurrentActiveUnits().PickRandom();
		actionFace.SecondBattleAction.CastTargetAmount(gameObject, actionFace.SecondModifiedActionValue, source);
	}
}
